"use client";
import React, { useState, useEffect } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Spinner } from "@/components/ui/spinner";
import {
  getAllReviews,
  getReviewStats,
  approveReview,
  publishReview,
  deleteReview,
  AdminReview,
  ReviewStats,
} from "@/lib/api/admin";
import {
  ChevronLeft,
  ChevronRight,
  Trash2,
  CheckCircle,
  XCircle,
  Eye,
  EyeOff,
} from "lucide-react";
import { toast } from "sonner";

export default function ReviewsManagement() {
  const [reviews, setReviews] = useState<AdminReview[]>([]);
  const [stats, setStats] = useState<ReviewStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [approvalFilter, setApprovalFilter] = useState<string>("all");
  const [selectedReview, setSelectedReview] = useState<AdminReview | null>(
    null
  );
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);

  useEffect(() => {
    loadReviews();
    loadStats();
  }, [page, approvalFilter]);

  async function loadReviews() {
    setLoading(true);
    try {
      const isApproved =
        approvalFilter === "all"
          ? undefined
          : approvalFilter === "approved"
          ? true
          : false;
      const data = await getAllReviews({
        page,
        limit: 10,
        isApproved,
      });
      setReviews(data.reviews);
      setTotalPages(data.pagination.totalPages);
    } catch (error: any) {
      toast.error(error.response?.data?.message || "Failed to load reviews");
    } finally {
      setLoading(false);
    }
  }

  async function loadStats() {
    try {
      const data = await getReviewStats();
      setStats(data);
    } catch (error: any) {
      console.error("Failed to load stats:", error);
    }
  }

  async function handleApprove(id: string, approved: boolean) {
    try {
      await approveReview(id, approved);
      toast.success(approved ? "Review approved" : "Review rejected");
      loadReviews();
      loadStats();
    } catch (error: any) {
      toast.error(error.response?.data?.message || "Failed to update review");
    }
  }

  async function handlePublish(id: string, published: boolean) {
    try {
      await publishReview(id, published);
      toast.success(published ? "Review published" : "Review unpublished");
      loadReviews();
    } catch (error: any) {
      toast.error(error.response?.data?.message || "Failed to update review");
    }
  }

  async function handleDeleteReview() {
    if (!selectedReview) return;
    try {
      await deleteReview(selectedReview.id);
      toast.success("Review deleted successfully");
      setDeleteDialogOpen(false);
      setSelectedReview(null);
      loadReviews();
      loadStats();
    } catch (error: any) {
      toast.error(error.response?.data?.message || "Failed to delete review");
    }
  }

  return (
    <div className="space-y-6">
      {/* Stats Cards */}
      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Card className="border-0 shadow-sm bg-white p-5">
            <p className="text-sm text-slate-500">Total Reviews</p>
            <p className="text-2xl font-semibold text-slate-800 mt-1">{stats.total}</p>
          </Card>
          <Card className="border-0 shadow-sm bg-white p-5">
            <p className="text-sm text-slate-500">Approved</p>
            <p className="text-2xl font-semibold text-emerald-600 mt-1">
              {stats.approved}
            </p>
          </Card>
          <Card className="border-0 shadow-sm bg-white p-5">
            <p className="text-sm text-slate-500">Pending</p>
            <p className="text-2xl font-semibold text-amber-600 mt-1">
              {stats.pending}
            </p>
          </Card>
          <Card className="border-0 shadow-sm bg-white p-5">
            <p className="text-sm text-slate-500">Average Rating</p>
            <p className="text-2xl font-semibold text-slate-800 mt-1">
              {stats.averageRating.toFixed(1)} <span className="text-amber-400">★</span>
            </p>
          </Card>
        </div>
      )}

      <Card className="border-0 shadow-sm bg-white">
        <div className="p-6 space-y-6">
          <div className="flex items-center gap-4">
            <Label className="text-slate-600 text-sm">Filter by Status:</Label>
            <Select value={approvalFilter} onValueChange={setApprovalFilter}>
              <SelectTrigger className="w-48 border-slate-200 focus:border-slate-400 focus:ring-slate-400">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All</SelectItem>
                <SelectItem value="approved">Approved</SelectItem>
                <SelectItem value="pending">Pending</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {loading ? (
            <div className="flex justify-center py-12">
              <Spinner className="h-6 w-6" />
            </div>
          ) : (
            <>
              <div className="rounded-lg border border-slate-200 overflow-hidden">
                <Table>
                  <TableHeader>
                    <TableRow className="bg-slate-50 hover:bg-slate-50">
                      <TableHead className="text-slate-600 font-medium">User</TableHead>
                      <TableHead className="text-slate-600 font-medium">Medicine</TableHead>
                      <TableHead className="text-slate-600 font-medium">Rating</TableHead>
                      <TableHead className="text-slate-600 font-medium">Message</TableHead>
                      <TableHead className="text-slate-600 font-medium">Status</TableHead>
                      <TableHead className="text-slate-600 font-medium">Visibility</TableHead>
                      <TableHead className="text-slate-600 font-medium">Date</TableHead>
                      <TableHead className="text-slate-600 font-medium text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {reviews.length === 0 ? (
                    <TableRow>
                      <TableCell
                        colSpan={8}
                        className="text-center text-slate-400 py-12"
                      >
                        No reviews found
                      </TableCell>
                    </TableRow>
                    ) : (
                      reviews.map((review) => (
                        <TableRow key={review.id} className="border-slate-100 hover:bg-slate-50/50">
                          <TableCell>
                            <div className="text-sm">
                              <p className="font-medium text-slate-700">
                                {review.user?.firstName} {review.user?.lastName}
                              </p>
                              <p className="text-slate-400 text-xs">
                                {review.user?.email}
                              </p>
                            </div>
                          </TableCell>
                          <TableCell>
                            <div className="text-sm">
                              <p className="font-medium text-slate-700">
                                {review.medicine?.title}
                              </p>
                              <p className="text-slate-400 text-xs">
                                {review.medicine?.brand}
                              </p>
                            </div>
                          </TableCell>
                          <TableCell>
                            <span className="text-amber-400 text-sm">
                              {"★".repeat(review.rating)}
                              <span className="text-slate-200">{"★".repeat(5 - review.rating)}</span>
                            </span>
                          </TableCell>
                          <TableCell className="max-w-xs">
                            <p className="truncate text-sm text-slate-600">{review.message}</p>
                          </TableCell>
                          <TableCell>
                            <span
                              className={`px-2.5 py-1 rounded-full text-xs font-medium ${
                                review.isApproved
                                  ? "bg-emerald-50 text-emerald-700"
                                  : "bg-amber-50 text-amber-700"
                              }`}
                            >
                              {review.isApproved ? "Approved" : "Pending"}
                            </span>
                          </TableCell>
                          <TableCell>
                            <span
                              className={`px-2.5 py-1 rounded-full text-xs font-medium ${
                                review.isPublished
                                  ? "bg-black text-white"
                                  : "bg-slate-100 text-slate-500"
                              }`}
                            >
                              {review.isPublished ? "Public" : "Hidden"}
                            </span>
                          </TableCell>
                          <TableCell className="text-slate-500 text-sm">
                            {new Date(review.createdAt).toLocaleDateString()}
                          </TableCell>
                          <TableCell className="text-right">
                            <div className="flex justify-end gap-1">
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() =>
                                  handleApprove(review.id, !review.isApproved)
                                }
                                title={review.isApproved ? "Reject" : "Approve"}
                                className="h-8 w-8 p-0 hover:bg-emerald-50"
                              >
                                {review.isApproved ? (
                                  <XCircle className="h-4 w-4 text-rose-500" />
                                ) : (
                                  <CheckCircle className="h-4 w-4 text-emerald-500" />
                                )}
                              </Button>
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() =>
                                  handlePublish(review.id, !review.isPublished)
                                }
                                title={review.isPublished ? "Hide" : "Publish"}
                                className="h-8 w-8 p-0 hover:bg-blue-50"
                              >
                                {review.isPublished ? (
                                  <EyeOff className="h-4 w-4 text-slate-400" />
                                ) : (
                                  <Eye className="h-4 w-4 text-blue-500" />
                                )}
                              </Button>
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => {
                                  setSelectedReview(review);
                                  setDeleteDialogOpen(true);
                                }}
                                className="h-8 w-8 p-0 hover:bg-red-50"
                              >
                                <Trash2 className="h-4 w-4 text-red-500" />
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </div>

              {totalPages > 1 && (
              <div className="flex justify-between items-center pt-2">
                  <p className="text-sm text-slate-500">
                    Page {page} of {totalPages}
                  </p>
                  <div className="flex gap-1">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setPage((p) => Math.max(1, p - 1))}
                      disabled={page === 1}
                      className="border-slate-200 text-slate-600 hover:bg-slate-50 disabled:opacity-40"
                    >
                      <ChevronLeft className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() =>
                        setPage((p) => Math.min(totalPages, p + 1))
                      }
                      disabled={page === totalPages}
                      className="border-slate-200 text-slate-600 hover:bg-slate-50 disabled:opacity-40"
                    >
                      <ChevronRight className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              )}
            </>
          )}
        </div>
      </Card>

      {/* Delete Confirmation Dialog */}
      <Dialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Confirm Deletion</DialogTitle>
          </DialogHeader>
          <p>
            Are you sure you want to delete this review? This action cannot be
            undone.
          </p>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setDeleteDialogOpen(false)}
            >
              Cancel
            </Button>
            <Button variant="destructive" onClick={handleDeleteReview}>
              Delete
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
